PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS accounts(id INTEGER PRIMARY KEY,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,salt TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('user','admin')));
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,account_id INTEGER NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cities(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE CHECK(length(trim(name))>0));
CREATE TABLE IF NOT EXISTS venues(id INTEGER PRIMARY KEY,city_id INTEGER NOT NULL REFERENCES cities(id),name TEXT NOT NULL CHECK(length(trim(name))>0),address TEXT NOT NULL,UNIQUE(city_id,name));
CREATE TABLE IF NOT EXISTS productions(id INTEGER PRIMARY KEY,title TEXT NOT NULL CHECK(length(trim(title))>0),description TEXT NOT NULL DEFAULT '',poster_url TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS runs(id INTEGER PRIMARY KEY,production_id INTEGER NOT NULL REFERENCES productions(id),venue_id INTEGER NOT NULL REFERENCES venues(id),start_date TEXT NOT NULL,end_date TEXT NOT NULL CHECK(end_date>=start_date),schedule_url TEXT NOT NULL DEFAULT '',seatmap_url TEXT NOT NULL DEFAULT '',published INTEGER NOT NULL DEFAULT 0 CHECK(published IN (0,1)));
CREATE TABLE IF NOT EXISTS performances(id INTEGER PRIMARY KEY,run_id INTEGER NOT NULL REFERENCES runs(id) ON DELETE CASCADE,starts_at TEXT NOT NULL,UNIQUE(run_id,starts_at));
CREATE TABLE IF NOT EXISTS actors(id INTEGER PRIMARY KEY,name TEXT NOT NULL CHECK(length(trim(name))>0));
CREATE TABLE IF NOT EXISTS characters(id INTEGER PRIMARY KEY,production_id INTEGER NOT NULL REFERENCES productions(id),name TEXT NOT NULL CHECK(length(trim(name))>0),UNIQUE(production_id,name));
CREATE TABLE IF NOT EXISTS casts(id INTEGER PRIMARY KEY,performance_id INTEGER NOT NULL REFERENCES performances(id) ON DELETE CASCADE,character_id INTEGER NOT NULL REFERENCES characters(id),actor_id INTEGER NOT NULL REFERENCES actors(id),UNIQUE(performance_id,character_id));
CREATE TABLE IF NOT EXISTS sale_rounds(id INTEGER PRIMARY KEY,run_id INTEGER NOT NULL REFERENCES runs(id) ON DELETE CASCADE,opens_at TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('priority','general')),note TEXT NOT NULL DEFAULT '',UNIQUE(run_id,opens_at,kind));
CREATE TABLE IF NOT EXISTS channels(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE,url TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS sale_channels(id INTEGER PRIMARY KEY,sale_round_id INTEGER NOT NULL REFERENCES sale_rounds(id) ON DELETE CASCADE,channel_id INTEGER NOT NULL REFERENCES channels(id),eligibility TEXT NOT NULL DEFAULT '',UNIQUE(sale_round_id,channel_id));
CREATE INDEX IF NOT EXISTS idx_sale_time ON sale_rounds(opens_at);
CREATE INDEX IF NOT EXISTS idx_runs_venue ON runs(venue_id);
CREATE TRIGGER IF NOT EXISTS performance_date_insert BEFORE INSERT ON performances BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM runs WHERE id=NEW.run_id AND substr(NEW.starts_at,1,10) BETWEEN start_date AND end_date) THEN RAISE(ABORT,'场次须在演出批次日期范围内') END; END;
CREATE TRIGGER IF NOT EXISTS performance_date_update BEFORE UPDATE ON performances BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM runs WHERE id=NEW.run_id AND substr(NEW.starts_at,1,10) BETWEEN start_date AND end_date) THEN RAISE(ABORT,'场次须在演出批次日期范围内') END; END;
CREATE TRIGGER IF NOT EXISTS run_date_update BEFORE UPDATE ON runs BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM performances WHERE run_id=OLD.id AND substr(starts_at,1,10) NOT BETWEEN NEW.start_date AND NEW.end_date) THEN RAISE(ABORT,'已有场次超出新日期范围') END; SELECT CASE WHEN EXISTS(SELECT 1 FROM casts ca JOIN performances pe ON ca.performance_id=pe.id JOIN characters ch ON ch.id=ca.character_id WHERE pe.run_id=OLD.id AND ch.production_id!=NEW.production_id) THEN RAISE(ABORT,'已有卡司不属于新剧目') END; END;
CREATE TRIGGER IF NOT EXISTS cast_insert BEFORE INSERT ON casts BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM performances p JOIN runs r ON p.run_id=r.id JOIN characters ch ON ch.production_id=r.production_id WHERE p.id=NEW.performance_id AND ch.id=NEW.character_id) THEN RAISE(ABORT,'角色必须属于该场次的剧目') END; END;
CREATE TRIGGER IF NOT EXISTS cast_update BEFORE UPDATE ON casts BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM performances p JOIN runs r ON p.run_id=r.id JOIN characters ch ON ch.production_id=r.production_id WHERE p.id=NEW.performance_id AND ch.id=NEW.character_id) THEN RAISE(ABORT,'角色必须属于该场次的剧目') END; END;
CREATE TRIGGER IF NOT EXISTS character_update BEFORE UPDATE ON characters BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM casts ca JOIN performances pe ON ca.performance_id=pe.id JOIN runs r ON r.id=pe.run_id WHERE ca.character_id=OLD.id AND r.production_id!=NEW.production_id) THEN RAISE(ABORT,'角色已有其他剧目场次引用') END; END;
CREATE TRIGGER IF NOT EXISTS performance_run_update BEFORE UPDATE ON performances BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM casts ca JOIN characters ch ON ch.id=ca.character_id JOIN runs r ON r.id=NEW.run_id WHERE ca.performance_id=OLD.id AND ch.production_id!=r.production_id) THEN RAISE(ABORT,'卡司与新批次剧目不匹配') END; END;
